module TopModule(
    input  logic clk,
    input  logic reset,
    input  logic [2:0] s,
    output logic fr2,
    output logic fr1,
    output logic fr0,
    output logic dfr
);

    // Water-level state: 0 = below s[0], 1 = between s[0]/s[1],
    //                    2 = between s[1]/s[2], 3 = above s[2]
    logic [1:0] level;
    logic       dfr_reg;
    logic [1:0] next_level;

    always_comb begin
        if (s[2])
            next_level = 2'd3;
        else if (s[1])
            next_level = 2'd2;
        else if (s[0])
            next_level = 2'd1;
        else
            next_level = 2'd0;
    end

    always_ff @(posedge clk) begin
        if (reset) begin
            level   <= 2'd0;
            dfr_reg <= 1'b1;
        end else begin
            level <= next_level;
            if (next_level == level)
                dfr_reg <= dfr_reg;
            else
                dfr_reg <= (next_level > level);
        end
    end

    always_comb begin
        fr2 = (level == 2'd0);
        fr1 = (level <= 2'd1);
        fr0 = (level <= 2'd2);
        dfr = dfr_reg;
    end

endmodule
```

